def checksum(s: str) -> int:
    """See SPEC.md."""
    values = []
    for ch in s:
        if '0' <= ch <= '9':
            values.append(ord(ch) - ord('0'))
        elif 'A' <= ch <= 'Z':
            values.append(ord(ch) - ord('A') + 10)
        else:
            raise ValueError(f"Invalid character: {ch!r}")

    total = 0
    for i, v in enumerate(reversed(values)):
        if i % 2 == 1:  # 2nd, 4th, ... from the right
            v *= 2
            if v > 35:
                v -= 35
        total += v

    return (36 - total % 36) % 36

